<style scoped lang="scss" src="./fundraiser-team-member-block.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";
import Button from "../button/button";
import { ButtonSize, ButtonMode } from "../button/button.constants";
import { currencyFormat } from "../../util/currency-format.js";

@Component({
  components: {
    Button
  }
})
export default class FundraiserTeamMemberBlock extends Vue {
  @Prop({ type: String, default: "" }) firstName;
  @Prop({ type: String, default: "" }) lastName;
  @Prop({ type: Number, default: 0 }) goal;
  @Prop({ type: Number, default: 0 }) collected;
  @Prop({ type: String, default: "" }) image;
  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues)
  })
  currency;

  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;

  get fullName() {
    return `${this.firstName} ${this.lastName}`;
  }

  get collectedString() {
    return currencyFormat(this.collected);
  }

  get goalString() {
    return currencyFormat(this.goal);
  }

  get meterStyle() {
    const ratio = this.goal
      ? Math.min((100 * this.collected) / this.goal, 100)
      : 100;

    return {
      clipPath: `polygon(0 6px, ${ratio}% 6px, ${ratio}% 8px, 0 8px)`
    };
  }

  handleClick() {
    /**
     * Emits when the button in this component is clicked.
     *
     * @event click
     */
    this.$emit("click");
  }
}
</script>

<template>
  <div class="FundraiserTeamMemberBlock">
    <div class="FundraiserTeamMemberBlock__Left">
      <div
        class="FundraiserTeamMemberBlock__Image"
        v-bind:style="{ backgroundImage: `url(${image})` }"
      />
      <div class="FundraiserTeamMemberBlock__Info">
        <div class="FundraiserTeamMemberBlock__Name">
          {{ fullName }}
        </div>
        <div v-if="this.goal > 0" class="FundraiserTeamMemberBlock__Summary">
          <span class="FundraiserTeamMemberBlock__Collected">
            {{ `${this.currency}${collectedString}` }}
          </span>
          <span class="FundraiserTeamMemberBlock__Goal">
            {{ ` of ${this.currency}${goalString} raised` }}
          </span>
        </div>
      </div>
    </div>
    <div class="FundraiserTeamMemberBlock__Right">
      <Button
        :mode="ButtonMode.PRIMARY"
        :label="`Donate to ${this.firstName}`"
        :size="ButtonSize.SMALL"
        :mobileSize="ButtonSize.SMALL"
        @click="handleClick"
      />
    </div>
    <div class="FundraiserTeamMemberBlock__Meter" :style="meterStyle" />
  </div>
</template>
